import sys, copy, json
sys.path.insert(0,'/workspace/submission')
import algo, exact, fab
# two nodes 0 anchored; node1? build: node0 anchor; two identical parallel links 0->1 (diff slots)
profile = {"groups":2,"jitter_ps":[0,0],"measurements":[[0,1,0,0]]}
fabric = {"n":2,"interval_ns":10,"slice_ns":40,"offset_ns":0,
 "drift_ppb":[0,0],"heat":[],"anchors":[[0,0,1]],
 "links":[{"ends":[[0,0,0],[1,0,1]],"delay_ns":[10,10],"defer_rounds":[0,0]},
          {"ends":[[0,1,0],[1,1,1]],"delay_ns":[10,10],"defer_rounds":[0,0]}],
 "slices":[[0,1]],"blackouts":[],"guards_ns":[0],"reconfig_ns":0}
plan = algo.compile_plan(profile, fabric)
print(json.dumps(plan))
# node1 both phases: from phase0 hop arrives p1; phase1 cell bound? anchor at p0 only; 
assert algo.audit(profile, fabric, plan) == {"valid": True}
# swap pred witness of the arriving cell to the other parallel link
mut = copy.deepcopy(plan)
P, N = plan['period_rounds'], 2
for p in range(P):
    for i in range(N):
        c = mut['pred'][p][i]
        if c and c[1] == 0:
            mut['pred'][p][i] = [c[0], 2]   # other link same endpoints
        elif c and c[1] == 2:
            mut['pred'][p][i] = [c[0], 0]
        elif c and c[1] == 1:
            mut['pred'][p][i] = [c[0], 3]
        elif c and c[1] == 3:
            mut['pred'][p][i] = [c[0], 1]
print('swapped audit:', algo.audit(profile, fabric, mut))
# wrong swap: point to a link whose endpoints differ -> must be false
mut2 = copy.deepcopy(plan)
for p in range(P):
    for i in range(2):
        if mut2['pred'][p][i] is not None and mut2['pred'][p][i][1] != -1:
            pv, kd = mut2['pred'][p][i]
            mut2['pred'][p][i] = [pv, (kd + 1) % 4]
print('broken audit:', algo.audit(profile, fabric, mut2))
PYEOF
